const s=$json;
const result={summary:`${s.name} is preparing for ${s.preferredRole || 'software roles'} with skills in ${s.skills}.`,skillScore:70,recommendedRoles:[{role:s.preferredRole||'Frontend Developer',matchPercentage:78,reason:'Matches the submitted skills and projects.'},{role:'Full Stack Developer',matchPercentage:72,reason:'Suitable after strengthening backend and database skills.'},{role:'Junior Software Engineer',matchPercentage:68,reason:'Good fresher-level entry role.'}],strongSkills:String(s.skills).split(',').map(x=>x.trim()).filter(Boolean).slice(0,5),missingSkills:['Data Structures and Algorithms','SQL practice','Deployment and debugging'],technicalQuestions:[{question:'Explain one project you built.',expectedAnswer:'Describe the problem, stack, your role, challenges and result.'},{question:'What is Git?',expectedAnswer:'A version control system used to track code changes.'},{question:'What is an API?',expectedAnswer:'A contract that allows software systems to communicate.'},{question:'What is deployment?',expectedAnswer:'Publishing an application so users can access it.'},{question:'What is the difference between frontend and backend?',expectedAnswer:'Frontend is the user interface; backend handles server logic and data.'}],hrQuestions:[{question:'Why should we hire you?',sampleAnswer:'I am a quick learner with practical project experience and a strong willingness to contribute.'},{question:'What are your strengths?',sampleAnswer:'Quick learning, problem-solving, teamwork and consistency.'},{question:'Where do you see yourself in five years?',sampleAnswer:'As a dependable software engineer taking ownership of important projects.'}],finalRecommendation:'Practise explaining projects, revise Git, deployment, APIs, n8n and AI concepts, and complete mock interviews.'};
return [{json:result}];
